-- Issue ...........: #279
-- Verification ....: docs/migrations/schema-baseline-verification.md
--
-- SCOPE
--   Included: schema `public` only — extensions in use, enum types, tables,
--   sequences, constraints, indexes, functions/procedures, triggers, RLS
--   enablement, RLS policies, grants/revokes, views, and comments.
--
--   Excluded: all row data; the `supabase_migrations` schema; anything owned
--   by Supabase-managed schemas (auth, storage, realtime, vault, extensions,
--   graphql, cron, pgsodium); role/user creation.
--
-- PREREQUISITES ON THE TARGET DATABASE
--   A stock Supabase project, so that the `auth`, `storage`, `extensions` and
--   `graphql` schemas and the `anon` / `authenticated` / `service_role` roles
--   already exist. Several foreign keys point at `auth.users`, and many
--   policies and functions reference `auth.uid()`.
--
-- APPLY WITH CARE. Read the verification report first.
-- ============================================================================

SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

-- Unqualified type names below (e.g. `access_code_type`) resolve against this
-- search_path, which matches the live database's setting for the app roles.
SET search_path = public, extensions;


-- ============================================================================
-- SECTION 1 — EXTENSIONS
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- Supabase-provisioned, present in the live database, not created here:
