CREATE TABLE public.access_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid NOT NULL,
    code text NOT NULL,
    code_type access_code_type DEFAULT 'permanent'::access_code_type NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    max_uses integer,
    current_uses integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    CONSTRAINT access_codes_code_key UNIQUE (code),
    CONSTRAINT access_codes_pkey PRIMARY KEY (id)
);

CREATE TABLE public.access_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    access_code_id uuid,
    contact_id uuid NOT NULL,
    resident_id uuid NOT NULL,
    check_in_time timestamp with time zone DEFAULT now() NOT NULL,
    check_out_time timestamp with time zone,
    verified_by uuid,
    gate_location text,
    notes text,
    flagged boolean DEFAULT false NOT NULL,
    flag_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expected_duration_minutes integer,
    actual_duration_minutes integer,
    vehicle_id uuid,
    entry_method text,
    photo_captured_at timestamp with time zone,
    photo_url text,
    CONSTRAINT access_logs_pkey PRIMARY KEY (id)
);

CREATE TABLE public.ai_conversation_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    user_role text DEFAULT 'resident'::text NOT NULL,
    message_count integer DEFAULT 0 NOT NULL,
    first_message text,
    full_transcript jsonb DEFAULT '[]'::jsonb,
