    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_conversation_logs_pkey PRIMARY KEY (id),
    CONSTRAINT ai_conversation_logs_user_role_check CHECK ((user_role = ANY (ARRAY['admin'::text, 'resident'::text, 'chairman'::text, 'financial_secretary'::text, 'security_officer'::text])))
);

CREATE TABLE public.ai_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text DEFAULT 'ollama'::text NOT NULL,
    model_name text DEFAULT 'mistral'::text NOT NULL,
    endpoint_url text DEFAULT 'http://localhost:11434'::text NOT NULL,
    api_key text,
    temperature numeric(3,2) DEFAULT 0.7 NOT NULL,
    max_tokens integer DEFAULT 2048 NOT NULL,
    system_prompt text DEFAULT 'You are a helpful estate management assistant. You help admins and residents with estate-related questions. Always be polite, concise, and factual. Never disclose information about other residents to unauthorized users.'::text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_settings_pkey PRIMARY KEY (id),
    CONSTRAINT ai_settings_max_tokens_check CHECK (((max_tokens > 0) AND (max_tokens <= 32768))),
    CONSTRAINT ai_settings_provider_check CHECK ((provider = ANY (ARRAY['ollama'::text, 'openai'::text, 'anthropic'::text, 'gemini'::text, 'groq'::text]))),
    CONSTRAINT ai_settings_temperature_check CHECK (((temperature >= (0)::numeric) AND (temperature <= (2)::numeric)))
);

