    CONSTRAINT email_transactions_match_confidence_check CHECK ((match_confidence = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text, 'none'::text, 'manual'::text]))),
    CONSTRAINT email_transactions_match_method_check CHECK ((match_method = ANY (ARRAY['alias'::text, 'phone'::text, 'name'::text, 'house_number'::text, 'manual'::text, 'keyword'::text]))),
    CONSTRAINT email_transactions_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['credit'::text, 'debit'::text])))
);

