    CONSTRAINT invoice_generation_runs_total_amount_check CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT invoice_generation_runs_total_wallet_allocated_check CHECK ((total_wallet_allocated >= (0)::numeric))
);

