    CONSTRAINT report_schedules_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT report_schedules_frequency_check CHECK ((frequency = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text, 'quarterly'::text, 'yearly'::text]))),
    CONSTRAINT report_schedules_period_preset_check CHECK ((period_preset = ANY (ARRAY['this_month'::text, 'last_month'::text, 'this_quarter'::text, 'last_quarter'::text, 'this_year'::text, 'last_year'::text]))),
    CONSTRAINT report_schedules_report_type_check CHECK ((report_type = ANY (ARRAY['financial_overview'::text, 'collection_report'::text, 'invoice_aging'::text, 'transaction_log'::text, 'debtors_report'::text, 'indebtedness_summary'::text, 'development_levy'::text]))),
    CONSTRAINT report_schedules_template_style_check CHECK ((template_style = ANY (ARRAY['traditional'::text, 'modern'::text])))
);

