    house_id uuid,
    menu_item text NOT NULL,
    pin_authenticated boolean DEFAULT false NOT NULL,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT whatsapp_disclosure_logs_pkey PRIMARY KEY (id)
);

CREATE TABLE public.whatsapp_link_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    resident_id uuid NOT NULL,
    token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    created_by uuid,
    CONSTRAINT whatsapp_link_tokens_token_hash_key UNIQUE (token_hash),
    CONSTRAINT whatsapp_link_tokens_pkey PRIMARY KEY (id)
);

CREATE TABLE public.whatsapp_optins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    resident_id uuid NOT NULL,
    phone_number text NOT NULL,
    opted_in boolean DEFAULT false NOT NULL,
    source text DEFAULT 'in_chat'::text NOT NULL,
    opted_in_at timestamp with time zone,
    opted_out_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT whatsapp_optins_resident_phone_key UNIQUE (resident_id, phone_number),
    CONSTRAINT whatsapp_optins_pkey PRIMARY KEY (id),
    CONSTRAINT whatsapp_optins_source_check CHECK ((source = ANY (ARRAY['in_chat'::text, 'admin_import'::text, 'admin'::text]))),
    CONSTRAINT whatsapp_optins_state_dates_check CHECK ((((opted_in = true) AND (opted_in_at IS NOT NULL) AND (opted_out_at IS NULL)) OR ((opted_in = false) AND (opted_out_at IS NOT NULL) AND (opted_in_at IS NULL)) OR ((opted_in = false) AND (opted_in_at IS NULL) AND (opted_out_at IS NULL))))
);

CREATE TABLE public.whatsapp_pending_contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phone_number text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    resident_id uuid,
    first_seen_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    last_seen_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    source text DEFAULT 'inbound'::text NOT NULL,
    CONSTRAINT whatsapp_pending_contacts_phone_number_key UNIQUE (phone_number),
    CONSTRAINT whatsapp_pending_contacts_pkey PRIMARY KEY (id),
    CONSTRAINT whatsapp_pending_contacts_source_check CHECK ((source = ANY (ARRAY['inbound'::text, 'link_code'::text, 'admin'::text]))),
    CONSTRAINT whatsapp_pending_contacts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'attached'::text, 'ignored'::text])))
);

CREATE TABLE public.whatsapp_processed_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id text NOT NULL,
    received_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT whatsapp_processed_messages_message_id_key UNIQUE (message_id),
    CONSTRAINT whatsapp_processed_messages_pkey PRIMARY KEY (id),
    CONSTRAINT whatsapp_processed_messages_expiry_check CHECK ((expires_at > received_at))
);

CREATE TABLE public.whatsapp_provider_credentials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    access_token_encrypted text,
    verify_token_encrypted text,
    app_secret_encrypted text,
    phone_number_id text,
    api_version text DEFAULT 'v23.0'::text,
    graph_base_url text DEFAULT 'https://graph.facebook.com'::text,
    account_sid_encrypted text,
    auth_token_encrypted text,
    whatsapp_from_number text,
    template_content_sids jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT whatsapp_provider_credentials_pkey PRIMARY KEY (id),
    CONSTRAINT whatsapp_provider_credentials_provider_check CHECK ((provider = ANY (ARRAY['meta'::text, 'twilio'::text])))
);

CREATE TABLE public.whatsapp_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phone_number text NOT NULL,
    resident_id uuid,
    current_node text DEFAULT 'menu'::text NOT NULL,
    selected_house_id uuid,
    pin_authenticated boolean DEFAULT false NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT whatsapp_sessions_phone_number_key UNIQUE (phone_number),
    CONSTRAINT whatsapp_sessions_pkey PRIMARY KEY (id)
);


