-- word_similarity_op, the trgm operator support functions and so on) and are
-- created by `CREATE EXTENSION pg_trgm` in Section 1 — re-issuing their
-- definitions here would fail, so they are deliberately NOT emitted. The 71
-- application-owned routines below are the full remainder.
--
-- Emitted verbatim from pg_get_functiondef, preserving SECURITY DEFINER and
-- every `SET search_path`. These are security-critical: do not reformat, and
-- do not "tidy" a SECURITY DEFINER marker away.

CREATE OR REPLACE FUNCTION public.approve_invoice_generation_run(p_run_id uuid, p_approver_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_run public.invoice_generation_runs%ROWTYPE; v_approval UUID;
BEGIN
  SELECT * INTO v_run FROM public.invoice_generation_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice generation run not found'; END IF;
  IF v_run.status <> 'awaiting_approval' THEN RAISE EXCEPTION 'Run is not awaiting approval'; END IF;
  IF v_run.requested_by = p_approver_id THEN RAISE EXCEPTION 'A distinct approver is required'; END IF;
  INSERT INTO public.invoice_generation_approvals(run_id, approver_id, decision, confirmation)
  VALUES (p_run_id, p_approver_id, 'approved', p_confirmation) RETURNING id INTO v_approval;
  UPDATE public.invoice_generation_runs SET status = 'queued', updated_at = now() WHERE id = p_run_id;
  RETURN jsonb_build_object('approval_id', v_approval, 'run', (SELECT to_jsonb(r) FROM public.invoice_generation_runs r WHERE r.id = p_run_id));
END; $function$;


CREATE OR REPLACE FUNCTION public.assert_active_super_admin_exists()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.app_roles ar ON ar.id = p.role_id
    WHERE p.approval_status = 'active'
      AND ar.name = 'super_admin'
  ) THEN
    RAISE EXCEPTION
      'At least one active account must hold the Super Administrator role'
      USING ERRCODE = 'restrict_violation',
            HINT = 'Grant Super Administrator to another active account before removing, '
                   'demoting or deactivating the last one.';
  END IF;

  RETURN NULL;
END;
$function$;


CREATE OR REPLACE FUNCTION public.calculate_visit_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  -- Calculate actual duration when check-out time is recorded
  IF NEW.check_out_time IS NOT NULL AND OLD.check_out_time IS NULL THEN
    NEW.actual_duration_minutes := EXTRACT(EPOCH FROM (NEW.check_out_time - NEW.check_in_time)) / 60;
  END IF;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.claim_invoice_generation_candidates(p_run_id uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(candidate_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_limit INTEGER := greatest(1, least(coalesce(p_limit, 50), 50)); v_status TEXT;
BEGIN
 SELECT status INTO v_status FROM public.invoice_generation_runs WHERE id = p_run_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invoice generation run not found'; END IF;
 IF v_status NOT IN ('queued','processing') THEN RETURN; END IF;
 UPDATE public.invoice_generation_candidates SET status='pending', claimed_at=NULL, updated_at=now()
 WHERE run_id=p_run_id AND status='processing' AND claimed_at < now() - interval '15 minutes';
 UPDATE public.invoice_generation_runs SET status='processing', started_at=coalesce(started_at,now()), updated_at=now() WHERE id=p_run_id;
 RETURN QUERY WITH claimable AS (SELECT id FROM public.invoice_generation_candidates WHERE run_id=p_run_id AND status='pending' ORDER BY created_at,id LIMIT v_limit FOR UPDATE SKIP LOCKED)
 UPDATE public.invoice_generation_candidates candidate SET status='processing', claimed_at=now(), updated_at=now() FROM claimable WHERE candidate.id=claimable.id RETURNING candidate.id;
END; $function$;


CREATE OR REPLACE FUNCTION public.create_generated_invoice(p_candidate_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_candidate public.invoice_generation_candidates%ROWTYPE;
    v_invoice_id UUID;
    v_invoice_number TEXT;
    v_wallet_result JSONB := '{}'::jsonb;
    v_wallet_allocated NUMERIC(12, 2) := 0;
    v_item JSONB;
    v_item_total NUMERIC(12, 2);
BEGIN
    IF auth.uid() IS NOT NULL AND (
        auth.uid() IS DISTINCT FROM p_actor_id
        OR NOT public.has_permission('billing.create_invoice')
    ) THEN
        RAISE EXCEPTION 'Not authorised to create generated invoices';
    END IF;

    SELECT * INTO v_candidate
    FROM public.invoice_generation_candidates
    WHERE id = p_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invoice generation candidate % not found', p_candidate_id;
    END IF;
    IF v_candidate.status IN ('created', 'skipped', 'cancelled') THEN
        RETURN jsonb_build_object(
            'status', v_candidate.status,
            'invoice_id', v_candidate.invoice_id,
            'amount', v_candidate.amount_due,
            'wallet_allocated', v_candidate.wallet_allocated
        );
    END IF;
    IF v_candidate.status = 'failed' THEN
        RAISE EXCEPTION 'Invoice generation candidate % has failed and must be retried explicitly', p_candidate_id;
    END IF;

    BEGIN
        IF jsonb_typeof(v_candidate.invoice_items) <> 'array'
           OR jsonb_array_length(v_candidate.invoice_items) = 0 THEN
            RAISE EXCEPTION 'Invoice generation candidate % requires at least one invoice item', p_candidate_id;
        END IF;

        SELECT sum((item ->> 'amount')::numeric)
        INTO v_item_total
        FROM jsonb_array_elements(v_candidate.invoice_items) AS item;

        IF v_item_total IS NULL OR v_item_total <> v_candidate.amount_due THEN
            RAISE EXCEPTION 'Invoice generation candidate % item total % does not equal amount due %',
                p_candidate_id, v_item_total, v_candidate.amount_due;
        END IF;

        UPDATE public.invoice_generation_candidates
        SET status = 'processing', updated_at = now()
        WHERE id = v_candidate.id;

        v_invoice_number := format(
            'INV-%s-%s-%s-%s',
            to_char(v_candidate.period_start, 'YYYYMM'),
            COALESCE(upper(substr(replace(v_candidate.house_id::text, '-', ''), 1, 8)), 'NOHOUSE'),
            upper(substr(replace(v_candidate.resident_id::text, '-', ''), 1, 8)),
            upper(substr(replace(v_candidate.billing_profile_version_id::text, '-', ''), 1, 8))
        );

        INSERT INTO public.invoices (
            resident_id, house_id, billing_profile_id, billing_profile_version_id, invoice_number,
            amount_due, amount_paid, status, due_date, period_start, period_end, created_by,
            invoice_type, rate_snapshot
        ) VALUES (
            v_candidate.resident_id, v_candidate.house_id, v_candidate.billing_profile_id,
            v_candidate.billing_profile_version_id, v_invoice_number, v_candidate.amount_due,
            0, 'unpaid', v_candidate.due_date, v_candidate.period_start, v_candidate.period_end,
            p_actor_id, v_candidate.invoice_type, v_candidate.rate_snapshot
        )
        ON CONFLICT (resident_id, house_id, billing_profile_version_id, period_start, period_end)
            WHERE billing_profile_version_id IS NOT NULL
            DO NOTHING
        RETURNING id INTO v_invoice_id;

        IF v_invoice_id IS NULL THEN
            SELECT id INTO v_invoice_id
            FROM public.invoices
            WHERE resident_id = v_candidate.resident_id
              AND house_id IS NOT DISTINCT FROM v_candidate.house_id
              AND billing_profile_version_id = v_candidate.billing_profile_version_id
              AND period_start = v_candidate.period_start
              AND period_end = v_candidate.period_end;

            UPDATE public.invoice_generation_candidates
            SET status = 'skipped',
                invoice_id = v_invoice_id,
                outcome = jsonb_build_object('reason', 'invoice_already_exists'),
                processed_at = now(),
                updated_at = now()
            WHERE id = v_candidate.id;

            RETURN jsonb_build_object(
                'status', 'skipped',
                'invoice_id', v_invoice_id,
                'amount', v_candidate.amount_due,
                'wallet_allocated', 0
            );
        END IF;

        FOR v_item IN
            SELECT value FROM jsonb_array_elements(v_candidate.invoice_items)
        LOOP
            INSERT INTO public.invoice_items (invoice_id, description, amount)
            VALUES (
                v_invoice_id,
                COALESCE(v_item ->> 'description', v_item ->> 'name'),
                (v_item ->> 'amount')::numeric
            );
        END LOOP;

        IF v_candidate.wallet_allocation_requested THEN
            v_wallet_result := public.settle_wallet_invoices(
                v_candidate.resident_id,
                ARRAY[v_invoice_id],
                'existing_wallet_settlement',
                current_date,
                NULL,
                v_candidate.house_id,
                0,
                v_candidate.amount_due,
                p_actor_id
            );
            v_wallet_allocated := COALESCE((v_wallet_result ->> 'total_allocated')::numeric, 0);
        END IF;

        UPDATE public.invoice_generation_candidates
        SET status = 'created',
            invoice_id = v_invoice_id,
            wallet_allocated = v_wallet_allocated,
            outcome = jsonb_build_object('wallet', v_wallet_result),
            processed_at = now(),
            updated_at = now()
        WHERE id = v_candidate.id;

        RETURN jsonb_build_object(
            'status', 'created',
            'invoice_id', v_invoice_id,
            'amount', v_candidate.amount_due,
            'wallet_allocated', v_wallet_allocated
        );
    EXCEPTION WHEN OTHERS THEN
        UPDATE public.invoice_generation_candidates
        SET status = 'failed',
            error_message = SQLERRM,
            processed_at = now(),
            updated_at = now()
        WHERE id = p_candidate_id;

        RETURN jsonb_build_object(
            'status', 'failed',
            'invoice_id', NULL,
            'amount', v_candidate.amount_due,
            'wallet_allocated', 0,
            'error', SQLERRM
        );
    END;
END;
$function$;


CREATE OR REPLACE FUNCTION public.create_personnel_resident_house_engagement(p_personnel_id uuid, p_resident_house_id uuid, p_responsibility text, p_start_date date, p_end_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_engagement_id uuid;
begin
  if p_start_date is null then raise exception 'Resident-House engagement start date is required'; end if;
  if p_end_date is not null and p_end_date < p_start_date then raise exception 'Engagement end date cannot be before its start date'; end if;
  insert into public.personnel_engagements (personnel_id, accountability_scope, resident_house_id, responsibility, start_date, end_date)
  values (p_personnel_id, 'resident_house', p_resident_house_id, nullif(p_responsibility, ''), p_start_date, p_end_date)
  returning id into v_engagement_id;
  return v_engagement_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.create_personnel_with_estate_engagement(p_personnel jsonb, p_responsibility text, p_start_date date, p_end_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_personnel_id uuid;
begin
  if p_start_date is null then
    raise exception 'Estate engagement start date is required';
  end if;

  if p_end_date is not null and p_end_date < p_start_date then
    raise exception 'Estate engagement end date cannot be before its start date';
  end if;

  insert into public.vendors (
    name,
    type,
    status,
    is_active,
    category,
    contact_person,
    email,
    phone,
    job_title,
    department,
    start_date,
    end_date,
    notes,
    bank_details
  )
  values (
    p_personnel->>'name',
    coalesce(p_personnel->>'type', 'vendor'),
    coalesce(p_personnel->>'status', 'active'),
    coalesce((p_personnel->>'is_active')::boolean, true),
    nullif(p_personnel->>'category', ''),
    nullif(p_personnel->>'contact_person', ''),
    nullif(p_personnel->>'email', ''),
    nullif(p_personnel->>'phone', ''),
    nullif(p_personnel->>'job_title', ''),
    nullif(p_personnel->>'department', ''),
    nullif(p_personnel->>'start_date', '')::date,
    nullif(p_personnel->>'end_date', '')::date,
    nullif(p_personnel->>'notes', ''),
    coalesce(p_personnel->'bank_details', '{}'::jsonb)
  )
  returning id into v_personnel_id;

  insert into public.personnel_engagements (
    personnel_id,
    accountability_scope,
    responsibility,
    start_date,
    end_date
  )
  values (
    v_personnel_id,
    'estate',
    nullif(p_responsibility, ''),
    p_start_date,
    p_end_date
  );

  return v_personnel_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.end_previous_impersonation_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  -- End any active sessions for this admin
  UPDATE impersonation_sessions
  SET is_active = false, ended_at = NOW()
  WHERE admin_profile_id = NEW.admin_profile_id
  AND is_active = true
  AND id != NEW.id;

  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.execute_property_transition(p_request_key text, p_transition_type text, p_house_id uuid, p_target_resident_id uuid, p_target_role resident_role, p_staff_actions jsonb, p_transition_date date, p_notes text, p_created_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing public.property_transition_requests%ROWTYPE;
    v_source public.resident_houses%ROWTYPE;
    v_target public.residents%ROWTYPE;
    v_source_role public.resident_role;
    v_stats JSONB;
    v_requested_count INTEGER;
    v_matched_count INTEGER;
BEGIN
    IF p_request_key IS NULL OR btrim(p_request_key) = '' THEN
        RAISE EXCEPTION 'Property transition request key is required';
    END IF;
    IF p_transition_type = 'developer_to_owner' THEN
        v_source_role := 'developer';
        IF p_target_role NOT IN ('resident_landlord', 'non_resident_landlord') THEN
            RAISE EXCEPTION 'Invalid owner role';
        END IF;
    ELSIF p_transition_type = 'landlord_to_tenant' THEN
        v_source_role := 'non_resident_landlord';
        IF p_target_role <> 'tenant' THEN
            RAISE EXCEPTION 'Invalid tenant role';
        END IF;
    ELSE
        RAISE EXCEPTION 'Unsupported property transition type';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
    SELECT * INTO v_existing FROM public.property_transition_requests WHERE request_key = p_request_key;
    IF FOUND THEN
        IF v_existing.house_id <> p_house_id THEN
            RAISE EXCEPTION 'Transition request key belongs to another property';
        END IF;
        RETURN v_existing.result || jsonb_build_object('existing', true);
    END IF;

    PERFORM 1 FROM public.houses WHERE id = p_house_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Property not found'; END IF;

    SELECT * INTO STRICT v_source
    FROM public.resident_houses
    WHERE house_id = p_house_id AND resident_role = v_source_role AND is_active = true
    FOR UPDATE;

    SELECT * INTO STRICT v_target
    FROM public.residents
    WHERE id = p_target_resident_id
    FOR UPDATE;

    IF v_target.entity_type = 'corporate' AND p_target_role IN ('resident_landlord', 'tenant') THEN
        RAISE EXCEPTION 'Corporate entity is not eligible for the requested role';
    END IF;
    IF EXISTS (SELECT 1 FROM public.resident_houses WHERE house_id = p_house_id AND resident_id = p_target_resident_id AND is_active = true) THEN
        RAISE EXCEPTION 'Target resident is already assigned to this property';
    END IF;
    IF p_transition_type = 'landlord_to_tenant' AND EXISTS (
        SELECT 1 FROM public.resident_houses WHERE house_id = p_house_id AND resident_role = 'tenant' AND is_active = true
    ) THEN
        RAISE EXCEPTION 'Property already has an active tenant';
    END IF;

    CREATE TEMP TABLE transition_staff_actions ON COMMIT DROP AS
    SELECT assignment_id, action, new_sponsor_id, keep_until_date
    FROM jsonb_to_recordset(COALESCE(p_staff_actions, '[]'::JSONB)) AS action_row(
        assignment_id UUID, action TEXT, new_sponsor_id UUID, keep_until_date DATE
    );

    IF EXISTS (SELECT 1 FROM transition_staff_actions WHERE action NOT IN ('remove', 'transfer', 'keep_until_date')) THEN
        RAISE EXCEPTION 'Invalid staff transition action';
    END IF;
    IF EXISTS (SELECT 1 FROM transition_staff_actions WHERE action = 'transfer' AND new_sponsor_id IS NULL AND p_transition_type = 'developer_to_owner') THEN
        RAISE EXCEPTION 'Transfer action requires a sponsor';
    END IF;

    SELECT COUNT(*) INTO v_requested_count FROM transition_staff_actions;
    PERFORM 1
    FROM public.resident_houses rh
    JOIN transition_staff_actions action_row ON action_row.assignment_id = rh.id
    WHERE rh.house_id = p_house_id AND rh.is_active = true
    FOR UPDATE OF rh;
    SELECT COUNT(*) INTO v_matched_count
    FROM public.resident_houses rh
    JOIN transition_staff_actions action_row ON action_row.assignment_id = rh.id
    WHERE rh.house_id = p_house_id AND rh.is_active = true;
    IF v_requested_count <> v_matched_count THEN
        RAISE EXCEPTION 'One or more staff assignments are unavailable';
    END IF;

    INSERT INTO public.house_ownership_history (house_id, resident_id, resident_role, event_type, event_date, notes, is_current, created_by)
    SELECT rh.house_id, rh.resident_id, rh.resident_role, 'move_out', p_transition_date,
           COALESCE(p_notes, 'Removed during property transition'), false, p_created_by
    FROM public.resident_houses rh
    JOIN transition_staff_actions action_row ON action_row.assignment_id = rh.id
    WHERE action_row.action = 'remove';

    UPDATE public.resident_houses rh
    SET is_active = false, move_out_date = p_transition_date
    FROM transition_staff_actions action_row
    WHERE action_row.assignment_id = rh.id AND action_row.action = 'remove';

    UPDATE public.resident_houses rh
    SET sponsor_resident_id = CASE WHEN p_transition_type = 'landlord_to_tenant' THEN p_target_resident_id ELSE action_row.new_sponsor_id END
    FROM transition_staff_actions action_row
    WHERE action_row.assignment_id = rh.id AND action_row.action = 'transfer';

    UPDATE public.resident_houses rh
    SET sponsor_resident_id = p_target_resident_id,
        tags = ARRAY['expires_' || COALESCE(action_row.keep_until_date, p_transition_date)::TEXT]
    FROM transition_staff_actions action_row
    WHERE action_row.assignment_id = rh.id AND action_row.action = 'keep_until_date';

    IF p_transition_type = 'developer_to_owner' THEN
        UPDATE public.resident_houses SET is_active = false, move_out_date = p_transition_date WHERE id = v_source.id;
    END IF;

    INSERT INTO public.resident_houses (resident_id, house_id, resident_role, move_in_date, move_out_date, is_active, created_by)
    VALUES (p_target_resident_id, p_house_id, p_target_role, p_transition_date, NULL, true, p_created_by)
    ON CONFLICT (resident_id, house_id) DO UPDATE
    SET resident_role = EXCLUDED.resident_role, move_in_date = EXCLUDED.move_in_date,
        move_out_date = NULL, is_active = true, created_by = EXCLUDED.created_by;

    UPDATE public.residents SET account_status = 'active', updated_by = p_created_by
    WHERE id = p_target_resident_id AND account_status = 'inactive';

    IF p_transition_type = 'developer_to_owner' THEN
        UPDATE public.house_ownership_history SET is_current = false WHERE house_id = p_house_id AND is_current = true;
        INSERT INTO public.house_ownership_history (house_id, resident_id, resident_role, event_type, event_date, notes, is_current, created_by)
        VALUES
            (p_house_id, v_source.resident_id, v_source.resident_role, 'ownership_end', p_transition_date, p_notes, false, p_created_by),
            (p_house_id, p_target_resident_id, p_target_role, 'ownership_transfer', p_transition_date, p_notes, true, p_created_by);
    ELSE
        INSERT INTO public.house_ownership_history (house_id, resident_id, resident_role, event_type, event_date, notes, is_current, created_by)
        VALUES (p_house_id, p_target_resident_id, p_target_role, 'move_in', p_transition_date, p_notes, true, p_created_by);
    END IF;

    SELECT jsonb_build_object(
        'staff_removed', COUNT(*) FILTER (WHERE action = 'remove'),
        'staff_transferred', COUNT(*) FILTER (WHERE action = 'transfer'),
        'staff_extended', COUNT(*) FILTER (WHERE action = 'keep_until_date')
    ) INTO v_stats FROM transition_staff_actions;

    v_stats := jsonb_build_object('success', true, 'stats', v_stats);
    INSERT INTO public.property_transition_requests (request_key, house_id, result) VALUES (p_request_key, p_house_id, v_stats);
    RETURN v_stats;
EXCEPTION
    WHEN NO_DATA_FOUND THEN RAISE EXCEPTION 'Required property transition record was not found';
    WHEN TOO_MANY_ROWS THEN RAISE EXCEPTION 'Property transition state is ambiguous';
END;
$function$;


CREATE OR REPLACE FUNCTION public.generate_access_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  new_code TEXT;
  code_exists BOOLEAN;
  max_attempts INTEGER := 100;
  attempt INTEGER := 0;
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- Excluding 0,O,1,I to avoid confusion
  part1 TEXT;
  part2 TEXT;
BEGIN
  LOOP
    attempt := attempt + 1;

    -- Generate first part (3 chars)
    part1 := '';
    FOR i IN 1..3 LOOP
      part1 := part1 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;

    -- Generate second part (4 chars)
    part2 := '';
    FOR i IN 1..4 LOOP
      part2 := part2 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;

    new_code := 'RES-' || part1 || '-' || part2;

    -- Check if code already exists
    SELECT EXISTS(
      SELECT 1 FROM access_codes WHERE code = new_code
    ) INTO code_exists;

    -- Exit loop if code is unique
    EXIT WHEN NOT code_exists;

    -- Safety check to prevent infinite loop
    IF attempt >= max_attempts THEN
      RAISE EXCEPTION 'Could not generate unique access code after % attempts', max_attempts;
    END IF;
  END LOOP;

  RETURN new_code;
END;
$function$;


CREATE OR REPLACE FUNCTION public.generate_house_shortname(p_street_id uuid, p_house_number text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
    v_street_code TEXT;
    v_shortname TEXT;
BEGIN
    -- Get street short_name
    SELECT short_name INTO v_street_code
    FROM public.streets
    WHERE id = p_street_id;

    -- If street has no short_name, return NULL (shortname is optional)
    IF v_street_code IS NULL THEN
        RETURN NULL;
    END IF;

    -- Generate shortname as: STREET_CODE-HOUSE_NUMBER
    -- Example: OAK-10A, ELM-5B
    v_shortname := UPPER(v_street_code) || '-' || UPPER(p_house_number);

    RETURN v_shortname;
END;
$function$;


CREATE OR REPLACE FUNCTION public.generate_resident_code()
 RETURNS character
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
    new_code CHAR(6);
    code_exists BOOLEAN;
    max_attempts INTEGER := 100;
    attempt INTEGER := 0;
BEGIN
    LOOP
        attempt := attempt + 1;

        -- Generate random 6-digit code (100000-999999)
        new_code := LPAD(FLOOR(RANDOM() * 900000 + 100000)::TEXT, 6, '0');

        -- Check if code already exists
        SELECT EXISTS(
            SELECT 1 FROM public.residents WHERE resident_code = new_code
        ) INTO code_exists;

        -- Exit loop if code is unique
        EXIT WHEN NOT code_exists;

        -- Safety check to prevent infinite loop
        IF attempt >= max_attempts THEN
            RAISE EXCEPTION 'Could not generate unique resident code after % attempts', max_attempts;
        END IF;
    END LOOP;

    RETURN new_code;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_effective_dashboard_theme(user_profile_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  override_theme TEXT;
  default_theme TEXT;
BEGIN
  -- Get user's override preference
  SELECT dashboard_theme_override
  INTO override_theme
  FROM profiles
  WHERE id = user_profile_id;

  -- If override is set, use it
  IF override_theme IS NOT NULL THEN
    RETURN override_theme;
  END IF;

  -- Otherwise, get estate default
  SELECT value
  INTO default_theme
  FROM system_settings
  WHERE category = 'appearance' AND key = 'dashboard_theme';

  -- Return default or fallback to 'nahid'
  RETURN COALESCE(default_theme, 'nahid');
END;
$function$;


