$function$;


CREATE OR REPLACE FUNCTION public.get_effective_setting(p_setting_key text, p_house_id uuid DEFAULT NULL::uuid, p_resident_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_actual_house_id UUID;
BEGIN
  -- If resident_id provided but no house_id, look up the house
  IF p_resident_id IS NOT NULL AND p_house_id IS NULL THEN
    SELECT rh.house_id INTO v_actual_house_id
    FROM resident_houses rh
    WHERE rh.resident_id = p_resident_id
    AND rh.is_active = true
    LIMIT 1;
  ELSE
    v_actual_house_id := p_house_id;
  END IF;

  -- Try resident level first (if resident_id provided)
  IF p_resident_id IS NOT NULL THEN
    SELECT value INTO v_result
    FROM hierarchical_settings
    WHERE setting_key = p_setting_key
    AND level = 'resident'
    AND resident_id = p_resident_id;

    IF v_result IS NOT NULL THEN
      RETURN v_result;
    END IF;
  END IF;

  -- Try house level (if house_id provided or derived from resident)
  IF v_actual_house_id IS NOT NULL THEN
    SELECT value INTO v_result
    FROM hierarchical_settings
    WHERE setting_key = p_setting_key
    AND level = 'house'
    AND house_id = v_actual_house_id;

    IF v_result IS NOT NULL THEN
      RETURN v_result;
    END IF;
  END IF;

  -- Fall back to estate level
  SELECT value INTO v_result
  FROM hierarchical_settings
  WHERE setting_key = p_setting_key
  AND level = 'estate';

  RETURN v_result;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_frequent_visitors(p_min_visits integer DEFAULT 5, p_days integer DEFAULT 30, p_limit integer DEFAULT 20)
 RETURNS TABLE(contact_id uuid, full_name text, phone_primary text, photo_url text, category_name text, resident_name text, resident_code text, visit_count bigint, last_visit_at timestamp with time zone, avg_duration_minutes integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    sc.id AS contact_id,
    sc.full_name,
    sc.phone_primary,
    sc.photo_url,
    cat.name AS category_name,
    (r.first_name || ' ' || r.last_name) AS resident_name,
    r.resident_code,
    COUNT(al.id) AS visit_count,
    MAX(al.check_in_time) AS last_visit_at,
    AVG(
      CASE WHEN al.check_out_time IS NOT NULL
        THEN EXTRACT(EPOCH FROM (al.check_out_time - al.check_in_time)) / 60
        ELSE NULL
      END
    )::INTEGER AS avg_duration_minutes
  FROM security_contacts sc
  JOIN access_logs al ON al.contact_id = sc.id
  LEFT JOIN security_contact_categories cat ON cat.id = sc.category_id
  LEFT JOIN residents r ON r.id = sc.resident_id
  WHERE
    sc.status = 'active'
    AND al.check_in_time >= NOW() - (p_days || ' days')::INTERVAL
  GROUP BY sc.id, sc.full_name, sc.phone_primary, sc.photo_url, cat.name, r.first_name, r.last_name, r.resident_code
  HAVING COUNT(al.id) >= p_min_visits
  ORDER BY visit_count DESC, last_visit_at DESC
  LIMIT p_limit;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_house_payment_status(p_house_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH base AS (
    SELECT i.id, i.amount_due, i.amount_paid, i.status, i.due_date, i.resident_id,
      r.first_name, r.last_name, r.resident_code,
      GREATEST(i.amount_due - i.amount_paid, 0) AS outstanding,
      (i.status IN ('unpaid', 'partially_paid') AND i.due_date IS NOT NULL AND i.due_date < CURRENT_DATE) AS is_overdue
    FROM public.invoices i LEFT JOIN public.residents r ON r.id = i.resident_id
    WHERE i.house_id = p_house_id AND i.status <> 'void'
  ), resident_totals AS (
    SELECT resident_id, MAX(first_name) AS first_name, MAX(last_name) AS last_name, MAX(resident_code) AS resident_code,
      SUM(amount_due) AS total_due, SUM(amount_paid) AS total_paid, SUM(outstanding) AS outstanding, COUNT(*) AS invoice_count
    FROM base WHERE resident_id IS NOT NULL GROUP BY resident_id
  ), totals AS (
    SELECT COALESCE(SUM(amount_due), 0) AS total_due, COALESCE(SUM(amount_paid), 0) AS total_paid,
      COALESCE(SUM(outstanding), 0) AS total_outstanding, COUNT(*) AS invoice_count,
      COUNT(*) FILTER (WHERE status = 'unpaid') AS unpaid_count,
      COUNT(*) FILTER (WHERE status = 'partially_paid') AS partially_paid_count,
      COUNT(*) FILTER (WHERE status = 'paid') AS paid_count,
      COUNT(*) FILTER (WHERE is_overdue) AS overdue_count,
      COALESCE(SUM(outstanding) FILTER (WHERE is_overdue), 0) AS overdue_amount
    FROM base
  )
  SELECT jsonb_build_object(
    'totalDue', totals.total_due, 'totalPaid', totals.total_paid, 'totalOutstanding', totals.total_outstanding,
    'invoiceCount', totals.invoice_count, 'unpaidCount', totals.unpaid_count,
    'partiallyPaidCount', totals.partially_paid_count, 'paidCount', totals.paid_count,
    'overdueCount', totals.overdue_count, 'overdueAmount', totals.overdue_amount,
    'residents', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'residentId', resident_id, 'residentName', concat_ws(' ', first_name, last_name), 'residentCode', resident_code,
        'totalDue', total_due, 'totalPaid', total_paid, 'outstanding', outstanding, 'invoiceCount', invoice_count
      ) ORDER BY outstanding DESC) FROM resident_totals
    ), '[]'::jsonb)
  ) FROM totals;
$function$;


CREATE OR REPLACE FUNCTION public.get_my_house_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
  SELECT house_id
  FROM resident_houses
  WHERE resident_id = get_my_resident_id()
    AND is_active = true;
$function$;


CREATE OR REPLACE FUNCTION public.get_my_permissions()
 RETURNS TABLE(permission_name text, category permission_category)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
    RETURN QUERY
    SELECT ap.name::TEXT, ap.category
    FROM profiles pr
    JOIN role_permissions rp ON rp.role_id = pr.role_id
    JOIN app_permissions ap ON ap.id = rp.permission_id
    WHERE pr.id = auth.uid()
      AND pr.approval_status = 'active'
      AND ap.is_active = TRUE;
END;
$function$;


