CREATE OR REPLACE FUNCTION public.get_primary_occupier(p_house_id uuid)
 RETURNS TABLE(resident_id uuid, first_name text, last_name text, email text, phone_primary text, resident_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    r.id,
    r.first_name,
    r.last_name,
    r.email,
    r.phone_primary,
    rh.resident_role::TEXT
  FROM resident_houses rh
  JOIN residents r ON rh.resident_id = r.id
  WHERE rh.house_id = p_house_id
  AND rh.is_active = true
  AND rh.resident_role IN ('resident_landlord', 'tenant')
  ORDER BY
    CASE rh.resident_role
      WHEN 'resident_landlord' THEN 1
      WHEN 'tenant' THEN 2
    END
  LIMIT 1;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_resident_cross_property_payment_summary(p_resident_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH current_houses AS (
    SELECT rh.house_id FROM public.resident_houses rh
    WHERE rh.resident_id = p_resident_id AND rh.is_active = true
  ), base AS (
    SELECT i.house_id, h.house_number, s.name AS street_name, i.amount_due, i.amount_paid, i.status, i.due_date,
      GREATEST(i.amount_due - i.amount_paid, 0) AS outstanding, (ch.house_id IS NOT NULL) AS is_current_property,
      (i.status IN ('unpaid', 'partially_paid') AND i.due_date IS NOT NULL AND i.due_date < CURRENT_DATE) AS is_overdue
    FROM public.invoices i JOIN public.houses h ON h.id = i.house_id
      LEFT JOIN public.streets s ON s.id = h.street_id LEFT JOIN current_houses ch ON ch.house_id = i.house_id
    WHERE i.resident_id = p_resident_id AND i.status <> 'void'
  ), property_totals AS (
    SELECT house_id, MAX(house_number) AS house_number, MAX(street_name) AS street_name,
      BOOL_OR(is_current_property) AS is_current_property, SUM(amount_due) AS total_due, SUM(amount_paid) AS total_paid,
      SUM(outstanding) AS outstanding, COUNT(*) AS invoice_count,
      COUNT(*) FILTER (WHERE status = 'unpaid') AS unpaid_count, COUNT(*) FILTER (WHERE is_overdue) AS overdue_count
    FROM base GROUP BY house_id
  )
  SELECT jsonb_build_object(
    'totalDue', COALESCE((SELECT SUM(amount_due) FROM base), 0),
    'totalPaid', COALESCE((SELECT SUM(amount_paid) FROM base), 0),
    'totalOutstanding', COALESCE((SELECT SUM(outstanding) FROM base), 0),
    'totalInvoices', (SELECT COUNT(*) FROM base),
    'properties', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'houseId', house_id, 'houseNumber', house_number, 'streetName', street_name,
        'isCurrentProperty', is_current_property, 'totalDue', total_due, 'totalPaid', total_paid,
        'outstanding', outstanding, 'invoiceCount', invoice_count, 'unpaidCount', unpaid_count, 'overdueCount', overdue_count
      ) ORDER BY outstanding DESC) FROM property_totals
    ), '[]'::jsonb)
  );
$function$;


CREATE OR REPLACE FUNCTION public.get_resident_indebtedness(p_resident_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'totalUnpaid', COALESCE(SUM(GREATEST(i.amount_due - i.amount_paid, 0)), 0),
    'invoiceCount', COUNT(*) FILTER (WHERE i.amount_due - i.amount_paid > 0),
    'unpaidCount', COUNT(*) FILTER (WHERE i.status = 'unpaid' AND i.amount_due - i.amount_paid > 0),
    'partiallyPaidCount', COUNT(*) FILTER (WHERE i.status = 'partially_paid' AND i.amount_due - i.amount_paid > 0)
  )
  FROM public.invoices i
  WHERE i.resident_id = p_resident_id AND i.status <> 'void';
$function$;


CREATE OR REPLACE FUNCTION public.get_setting_overrides(p_setting_key text)
 RETURNS TABLE(level setting_level, house_id uuid, resident_id uuid, value jsonb, reference_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    hs.level,
    hs.house_id,
    hs.resident_id,
    hs.value,
    CASE
      WHEN hs.level = 'estate' THEN 'Estate Default'
      WHEN hs.level = 'house' THEN h.house_number || ' ' || COALESCE(s.name, '')
      WHEN hs.level = 'resident' THEN r.first_name || ' ' || r.last_name
    END as reference_name
  FROM hierarchical_settings hs
  LEFT JOIN houses h ON hs.house_id = h.id
  LEFT JOIN streets s ON h.street_id = s.id
  LEFT JOIN residents r ON hs.resident_id = r.id
  WHERE hs.setting_key = p_setting_key
  ORDER BY
    CASE hs.level
      WHEN 'estate' THEN 1
      WHEN 'house' THEN 2
      WHEN 'resident' THEN 3
    END,
    reference_name;
END;
$function$;


CREATE OR REPLACE FUNCTION public.get_visitor_history_summary(p_contact_id uuid, p_days integer DEFAULT 90)
 RETURNS TABLE(total_visits bigint, first_visit timestamp with time zone, last_visit timestamp with time zone, avg_duration_minutes integer, total_duration_hours numeric, most_common_gate text, flagged_visits bigint, vehicles_used bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(al.id) AS total_visits,
    MIN(al.check_in_time) AS first_visit,
    MAX(al.check_in_time) AS last_visit,
    AVG(al.actual_duration_minutes)::INTEGER AS avg_duration_minutes,
    ROUND(SUM(COALESCE(al.actual_duration_minutes, 0)) / 60.0, 2) AS total_duration_hours,
    (
      SELECT al2.gate_location
      FROM access_logs al2
      WHERE al2.contact_id = p_contact_id
      AND al2.gate_location IS NOT NULL
      GROUP BY al2.gate_location
      ORDER BY COUNT(*) DESC
      LIMIT 1
    ) AS most_common_gate,
    SUM(CASE WHEN al.flagged THEN 1 ELSE 0 END) AS flagged_visits,
    COUNT(DISTINCT al.vehicle_id) AS vehicles_used
  FROM access_logs al
  WHERE
    al.contact_id = p_contact_id
    AND al.check_in_time >= NOW() - (p_days || ' days')::INTERVAL;
END;
$function$;


CREATE OR REPLACE FUNCTION public.handle_house_shortname()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
    v_generated_shortname TEXT;
BEGIN
    -- Only auto-generate if short_name is not explicitly provided
    IF NEW.short_name IS NULL THEN
        v_generated_shortname := public.generate_house_shortname(NEW.street_id, NEW.house_number);
        NEW.short_name := v_generated_shortname;
    END IF;

    RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
    INSERT INTO public.profiles (id, email, full_name, role_id, approval_status)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(
            NULLIF(TRIM(NEW.raw_user_meta_data->>'full_name'), ''),
            NULLIF(TRIM(NEW.raw_user_meta_data->>'name'), ''),
            NEW.email
        ),
        NULL,       -- role_id: assigned by an administrator on approval
        'pending'   -- no access until approved
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION public.has_permission(p_permission_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
    v_has_perm BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM profiles pr
        JOIN role_permissions rp ON rp.role_id = pr.role_id
        JOIN app_permissions ap ON ap.id = rp.permission_id
        WHERE pr.id = auth.uid()
          AND pr.approval_status = 'active'
          AND ap.name = p_permission_name
          AND ap.is_active = TRUE
    ) INTO v_has_perm;

    RETURN COALESCE(v_has_perm, FALSE);
END;
$function$;


CREATE OR REPLACE FUNCTION public.import_legacy_financial_batch(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  invoice_count integer := 0;
  payment_count integer := 0;
  wallet_count integer := 0;
  transaction_count integer := 0;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  INSERT INTO public.invoices (
    id, resident_id, house_id, billing_profile_id, invoice_number,
    amount_due, amount_paid, status, due_date, period_start, period_end,
    created_by, rate_snapshot
  )
  SELECT id, resident_id, house_id, billing_profile_id, invoice_number,
         amount_due, amount_paid, status::invoice_status, due_date::date,
         period_start::date, period_end::date, created_by, rate_snapshot::jsonb
  FROM jsonb_to_recordset(coalesce(payload->'invoices', '[]'::jsonb)) AS x(
    id uuid, resident_id uuid, house_id uuid, billing_profile_id uuid,
    invoice_number text, amount_due numeric, amount_paid numeric,
    status text, due_date text, period_start text, period_end text,
    created_by uuid, rate_snapshot text
  )
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS invoice_count = ROW_COUNT;

  INSERT INTO public.payment_records (
    id, resident_id, house_id, amount, payment_date, period_start,
    period_end, status, method
  )
  SELECT id, resident_id, house_id, amount, payment_date::date,
         period_start::date, period_end::date, status::payment_status,
         method::payment_method
  FROM jsonb_to_recordset(coalesce(payload->'payments', '[]'::jsonb)) AS x(
    id uuid, resident_id uuid, house_id uuid, amount numeric,
    payment_date text, period_start text, period_end text,
    status text, method text
  )
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS payment_count = ROW_COUNT;

  INSERT INTO public.resident_wallets (id, resident_id, balance)
  SELECT id, resident_id, balance
  FROM jsonb_to_recordset(coalesce(payload->'wallets', '[]'::jsonb)) AS x(
    id uuid, resident_id uuid, balance numeric
  )
  ON CONFLICT (id) DO UPDATE SET balance = excluded.balance, updated_at = now();
  GET DIAGNOSTICS wallet_count = ROW_COUNT;

  INSERT INTO public.wallet_transactions (
    id, wallet_id, type, amount, balance_after, reference_type,
    reference_id, description
  )
  SELECT id, wallet_id, type::wallet_transaction_type, amount,
         balance_after, reference_type, reference_id, description
  FROM jsonb_to_recordset(coalesce(payload->'wallet_transactions', '[]'::jsonb)) AS x(
    id uuid, wallet_id uuid, type text, amount numeric, balance_after numeric,
    reference_type text, reference_id uuid, description text
  )
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS transaction_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'invoices', invoice_count,
    'payments', payment_count,
    'wallets', wallet_count,
    'wallet_transactions', transaction_count
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.increment_access_code_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
BEGIN
  -- Only increment if access_code_id is provided
  IF NEW.access_code_id IS NOT NULL THEN
    UPDATE access_codes
    SET current_uses = current_uses + 1
    WHERE id = NEW.access_code_id;

    -- Deactivate one-time codes after use
    UPDATE access_codes
    SET is_active = false
    WHERE id = NEW.access_code_id
      AND code_type = 'one_time'
      AND max_uses IS NOT NULL
      AND current_uses >= max_uses;
  END IF;

  RETURN NEW;
END;
$function$;


