 RETURNS text
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
    SELECT 'RCP-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-' || lpad(nextval('public.wallet_receipt_number_seq')::text, 5, '0');
$function$;


CREATE OR REPLACE FUNCTION public.prevent_locked_billing_profile_version_item_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.billing_profile_versions
        WHERE id = OLD.billing_profile_version_id
          AND is_locked
    ) THEN
        RAISE EXCEPTION 'Items for locked billing profile version % are immutable', OLD.billing_profile_version_id
            USING ERRCODE = '55000';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;


CREATE OR REPLACE FUNCTION public.prevent_locked_billing_profile_version_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF OLD.is_locked THEN
        RAISE EXCEPTION 'Locked billing profile version % is immutable', OLD.id
            USING ERRCODE = '55000';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;


CREATE OR REPLACE FUNCTION public.process_expired_approvals()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE approval_requests
  SET
    status = 'rejected',
    reviewed_at = NOW(),
    review_notes = 'Auto-rejected: No response within 72 hours',
    updated_at = NOW()
  WHERE status = 'pending'
  AND expires_at IS NOT NULL
  AND expires_at <= NOW();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;


CREATE OR REPLACE FUNCTION public.record_ownership_history(p_house_id uuid, p_resident_id uuid, p_resident_role resident_role, p_event_type text, p_previous_role resident_role DEFAULT NULL::resident_role, p_event_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text, p_is_current boolean DEFAULT false, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_history_id UUID;
BEGIN
  -- If marking as current owner, clear previous current owner flags for this house
  IF p_is_current AND p_event_type IN ('ownership_start', 'ownership_transfer') THEN
    UPDATE house_ownership_history
    SET is_current = false
    WHERE house_id = p_house_id
      AND is_current = true
      AND resident_role IN ('resident_landlord', 'non_resident_landlord', 'developer');
  END IF;

  -- If marking as current occupant, clear previous current occupant flags
  IF p_is_current AND p_event_type = 'move_in' AND p_resident_role IN ('resident_landlord', 'tenant') THEN
    UPDATE house_ownership_history
    SET is_current = false
    WHERE house_id = p_house_id
      AND is_current = true
      AND resident_role IN ('resident_landlord', 'tenant');
  END IF;

  INSERT INTO house_ownership_history (
    house_id,
    resident_id,
    resident_role,
    event_type,
    previous_role,
    event_date,
    notes,
    is_current,
    created_by
  ) VALUES (
    p_house_id,
    p_resident_id,
    p_resident_role,
    p_event_type,
    p_previous_role,
    p_event_date,
    p_notes,
    p_is_current,
    p_created_by
  )
  RETURNING id INTO v_history_id;

  RETURN v_history_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public.refresh_invoice_generation_run(p_run_id uuid)
 RETURNS invoice_generation_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_run public.invoice_generation_runs%ROWTYPE;
BEGIN
  UPDATE public.invoice_generation_runs run
  SET candidate_count = summary.candidate_count,
      created_count = summary.created_count,
      skipped_count = summary.skipped_count,
      failed_count = summary.failed_count,
      cancelled_count = summary.cancelled_count,
      total_wallet_allocated = summary.total_wallet_allocated,
      email_queued_count = summary.email_queued_count,
      email_sent_count = summary.email_sent_count,
      email_failed_count = summary.email_failed_count,
      status = CASE WHEN run.status = 'cancelled' THEN 'cancelled'
                    WHEN summary.pending_count > 0 OR summary.processing_count > 0 THEN 'processing'
                    WHEN summary.failed_count > 0 THEN 'completed_with_errors' ELSE 'completed' END,
      completed_at = CASE WHEN summary.pending_count = 0 AND summary.processing_count = 0 THEN coalesce(run.completed_at, now()) ELSE NULL END,
      result_summary = jsonb_build_object(
        'pending', summary.pending_count,
        'processing', summary.processing_count,
        'created', summary.created_count,
        'skipped', summary.skipped_count,
        'failed', summary.failed_count,
        'cancelled', summary.cancelled_count,
        'email_queued', summary.email_queued_count,
        'email_sent', summary.email_sent_count,
        'email_failed', summary.email_failed_count
      ) || coalesce(run.result_summary - ARRAY['pending','processing','created','skipped','failed','cancelled','email_queued','email_sent','email_failed']::text[], '{}'::jsonb),
      updated_at = now()
  FROM (
    SELECT count(*)::integer AS candidate_count,
      count(*) FILTER (WHERE c.status = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE c.status = 'processing')::integer AS processing_count,
      count(*) FILTER (WHERE c.status = 'created')::integer AS created_count,
      count(*) FILTER (WHERE c.status = 'skipped')::integer AS skipped_count,
      count(*) FILTER (WHERE c.status = 'failed')::integer AS failed_count,
      count(*) FILTER (WHERE c.status = 'cancelled')::integer AS cancelled_count,
      coalesce(sum(c.wallet_allocated), 0) AS total_wallet_allocated,
      count(*) FILTER (WHERE q.status IN ('pending', 'processing') OR c.email_status = 'queued')::integer AS email_queued_count,
      count(*) FILTER (WHERE q.status = 'sent' OR c.email_status = 'sent')::integer AS email_sent_count,
      count(*) FILTER (WHERE q.status = 'failed' OR c.email_status = 'failed')::integer AS email_failed_count
    FROM public.invoice_generation_candidates c
    LEFT JOIN public.notification_queue q ON q.id = c.email_queue_id
    WHERE c.run_id = p_run_id
  ) summary
  WHERE run.id = p_run_id
  RETURNING run.* INTO v_run;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice generation run % not found', p_run_id; END IF;
  RETURN v_run;
END;
$function$;


CREATE OR REPLACE FUNCTION public.replace_whatsapp_credentials(p_provider text, p_access_token_encrypted text DEFAULT NULL::text, p_verify_token_encrypted text DEFAULT NULL::text, p_app_secret_encrypted text DEFAULT NULL::text, p_phone_number_id text DEFAULT NULL::text, p_api_version text DEFAULT 'v23.0'::text, p_graph_base_url text DEFAULT 'https://graph.facebook.com'::text, p_account_sid_encrypted text DEFAULT NULL::text, p_auth_token_encrypted text DEFAULT NULL::text, p_whatsapp_from_number text DEFAULT NULL::text, p_template_content_sids jsonb DEFAULT NULL::jsonb, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS whatsapp_provider_credentials
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row whatsapp_provider_credentials;
BEGIN
  IF p_provider NOT IN ('meta', 'twilio') THEN
    RAISE EXCEPTION 'Invalid WhatsApp provider: %', p_provider;
  END IF;

  UPDATE whatsapp_provider_credentials
  SET is_active = FALSE,
      updated_at = NOW(),
      updated_by = p_actor_id
  WHERE is_active = TRUE;

  INSERT INTO whatsapp_provider_credentials (
    provider, is_active, access_token_encrypted, verify_token_encrypted,
    app_secret_encrypted, phone_number_id, api_version, graph_base_url,
    account_sid_encrypted, auth_token_encrypted, whatsapp_from_number,
    template_content_sids, created_by, updated_by
  ) VALUES (
    p_provider, TRUE, p_access_token_encrypted, p_verify_token_encrypted,
    p_app_secret_encrypted, p_phone_number_id,
    COALESCE(p_api_version, 'v23.0'),
    COALESCE(p_graph_base_url, 'https://graph.facebook.com'),
    p_account_sid_encrypted, p_auth_token_encrypted, p_whatsapp_from_number,
    p_template_content_sids, p_actor_id, p_actor_id
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;


CREATE OR REPLACE FUNCTION public.requires_approval_for_action(p_house_id uuid, p_requester_resident_id uuid, p_action_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_requester_role TEXT;
  v_has_occupier BOOLEAN;
BEGIN
  -- Get requester's role at this house
  SELECT resident_role INTO v_requester_role
  FROM resident_houses
  WHERE house_id = p_house_id
  AND resident_id = p_requester_resident_id
  AND is_active = true
  LIMIT 1;

  -- Only developers and non_resident_landlords need approval
  IF v_requester_role NOT IN ('developer', 'non_resident_landlord') THEN
    RETURN FALSE;
  END IF;

  -- Check if there's an active owner-occupier or tenant
  SELECT EXISTS(
    SELECT 1 FROM resident_houses
    WHERE house_id = p_house_id
    AND is_active = true
    AND resident_id != p_requester_resident_id
    AND resident_role IN ('resident_landlord', 'tenant')
  ) INTO v_has_occupier;

  RETURN v_has_occupier;
END;
$function$;


CREATE OR REPLACE FUNCTION public.reverse_wallet_payment_batch(p_batch_id uuid, p_reversed_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_batch wallet_payment_batches%ROWTYPE;
    v_item RECORD;
    v_wallet resident_wallets%ROWTYPE;
    v_total_allocated DECIMAL(12, 2) := 0;
    v_source_credit DECIMAL(12, 2) := 0;
    v_new_balance DECIMAL(12, 2);
BEGIN
    SELECT * INTO v_batch FROM wallet_payment_batches WHERE id = p_batch_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Wallet payment batch not found'; END IF;
    IF v_batch.status <> 'completed' THEN RAISE EXCEPTION 'Wallet payment batch has already been reversed'; END IF;

    SELECT * INTO v_wallet FROM resident_wallets WHERE resident_id = v_batch.resident_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Resident wallet not found'; END IF;

    FOR v_item IN SELECT * FROM wallet_payment_batch_items WHERE batch_id = p_batch_id ORDER BY created_at DESC FOR UPDATE LOOP
        UPDATE invoices
        SET amount_paid = GREATEST(0, amount_paid - v_item.amount_allocated),
            status = CASE WHEN GREATEST(0, amount_paid - v_item.amount_allocated) = 0 THEN 'unpaid'::invoice_status ELSE 'partially_paid'::invoice_status END
        WHERE id = v_item.invoice_id;
        v_total_allocated := v_total_allocated + v_item.amount_allocated;
    END LOOP;

    v_new_balance := v_wallet.balance + v_total_allocated;
    IF v_batch.source_payment_id IS NOT NULL THEN
        SELECT COALESCE(SUM(amount), 0) INTO v_source_credit
        FROM wallet_transactions
        WHERE wallet_id = v_wallet.id AND type = 'credit' AND reference_type = 'payment' AND reference_id = v_batch.source_payment_id;
        v_new_balance := v_new_balance - v_source_credit;
    END IF;

    UPDATE resident_wallets SET balance = v_new_balance WHERE id = v_wallet.id;
    INSERT INTO wallet_transactions (wallet_id, type, amount, balance_after, reference_type, reference_id, description)
    VALUES (v_wallet.id, 'credit', v_total_allocated, v_wallet.balance + v_total_allocated, 'batch_reversal', p_batch_id, 'Reversal of invoice allocation');
    IF v_source_credit > 0 THEN
        INSERT INTO wallet_transactions (wallet_id, type, amount, balance_after, reference_type, reference_id, description)
        VALUES (v_wallet.id, 'debit', v_source_credit, v_new_balance, 'batch_reversal', p_batch_id, 'Reversal of source payment credit');
    END IF;
    UPDATE wallet_payment_batches SET status = 'reversed', updated_at = NOW() WHERE id = p_batch_id;

    RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id, 'new_wallet_balance', v_new_balance, 'total_reversed', v_total_allocated);
END;
$function$;


