CREATE OR REPLACE VIEW public.security_settings_view AS
 SELECT key,
        CASE key
            WHEN 'security_role_permissions'::text THEN COALESCE(value, '{"verify_codes": ["admin", "chairman", "financial_secretary", "security_officer"], "view_contacts": ["admin", "chairman", "financial_secretary", "security_officer"], "generate_codes": ["admin", "chairman", "financial_secretary"], "record_checkin": ["admin", "chairman", "financial_secretary", "security_officer"], "export_contacts": ["admin", "chairman", "financial_secretary", "security_officer"], "search_contacts": ["admin", "chairman", "financial_secretary", "security_officer"], "update_contacts": ["admin", "chairman", "financial_secretary"], "view_access_logs": ["admin", "chairman"], "register_contacts": ["admin", "chairman", "financial_secretary"], "configure_categories": ["admin"], "suspend_revoke_contacts": ["admin", "chairman"]}'::jsonb)
            WHEN 'security_max_contacts_per_resident'::text THEN COALESCE(value, 'null'::jsonb)
            WHEN 'security_mandatory_fields'::text THEN COALESCE(value, '["full_name", "phone_primary", "category_id"]'::jsonb)
            WHEN 'security_code_format'::text THEN COALESCE(value, '"alphanumeric"'::jsonb)
            WHEN 'security_expiry_warning_days'::text THEN COALESCE(value, '[7, 3, 1]'::jsonb)
            WHEN 'security_auto_expire_contacts'::text THEN COALESCE(value, 'true'::jsonb)
            ELSE value
        END AS value,
    description,
    updated_at
   FROM system_settings
  WHERE category = 'security'::text;

CREATE OR REPLACE VIEW public.visitor_analytics AS
 SELECT sc.id AS contact_id,
    sc.full_name,
    sc.resident_id,
    sc.category_id,
    sc.is_recurring,
    sc.is_frequent_visitor,
    sc.visit_count,
    sc.last_visit_at,
    sc.status,
    cat.name AS category_name,
    r.first_name AS resident_first_name,
    r.last_name AS resident_last_name,
    r.resident_code,
    ( SELECT count(*) AS count
           FROM access_logs al
          WHERE al.contact_id = sc.id AND al.check_in_time >= (now() - '30 days'::interval)) AS visits_last_30_days,
    ( SELECT count(*) AS count
           FROM access_logs al
          WHERE al.contact_id = sc.id AND al.check_in_time >= (now() - '7 days'::interval)) AS visits_last_7_days,
    ( SELECT avg(EXTRACT(epoch FROM al.check_out_time - al.check_in_time) / 60::numeric)::integer AS avg
           FROM access_logs al
          WHERE al.contact_id = sc.id AND al.check_out_time IS NOT NULL) AS avg_visit_duration_minutes,
    ( SELECT count(*) AS count
           FROM visitor_vehicles vv
          WHERE vv.contact_id = sc.id AND vv.is_active = true) AS vehicle_count
   FROM security_contacts sc
     LEFT JOIN security_contact_categories cat ON cat.id = sc.category_id
     LEFT JOIN residents r ON r.id = sc.resident_id
  WHERE sc.status = 'active'::security_contact_status;

-- There are no materialized views in the live database.


