CREATE POLICY "Residents can view own access codes" ON public.access_codes AS PERMISSIVE FOR SELECT TO authenticated
  USING ((contact_id IN ( SELECT security_contacts.id
   FROM security_contacts
  WHERE (security_contacts.resident_id = get_my_resident_id()))));
CREATE POLICY access_codes_delete_policy ON public.access_codes AS PERMISSIVE FOR DELETE TO authenticated
  USING ((get_my_role_name() = ANY (ARRAY['super_admin'::text, 'chairman'::text, 'vice_chairman'::text])));
CREATE POLICY access_codes_insert_policy ON public.access_codes AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((get_my_role_name() = ANY (ARRAY['super_admin'::text, 'chairman'::text, 'vice_chairman'::text, 'financial_officer'::text])));
CREATE POLICY access_codes_select_policy ON public.access_codes AS PERMISSIVE FOR SELECT TO authenticated
  USING ((get_my_role_name() = ANY (ARRAY['super_admin'::text, 'chairman'::text, 'vice_chairman'::text, 'financial_officer'::text, 'security_officer'::text])));
CREATE POLICY access_codes_update_policy ON public.access_codes AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((get_my_role_name() = ANY (ARRAY['super_admin'::text, 'chairman'::text, 'vice_chairman'::text, 'financial_officer'::text, 'security_officer'::text])));
