-- ============================================================================
-- SECTION 12 — GRANTS AND REVOKES
-- ============================================================================
-- A stock Supabase project carries ALTER DEFAULT PRIVILEGES in `public` that
-- grant ALL on new tables/sequences and EXECUTE on new functions to `anon`,
-- `authenticated` and `service_role`. This section therefore does two things:
--   1. Grants explicitly, so the file is correct even without those defaults.
--   2. REVOKES explicitly wherever the live database is narrower than the
--      default. Those revokes are load-bearing — several of them are the only
--      thing keeping `anon` away from SECURITY DEFINER functions and from
--      WhatsApp / personnel / invoice-generation tables. Do not "simplify"
--      this section by deleting the REVOKEs.
--
-- Schema usage (matches the live grants on schema public):
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 12a. Tables — the common case (84 of 97)
-- ---------------------------------------------------------------------------
-- Everything not named in 12b/12c/12d/12e below carries
--   postgres / anon / authenticated / service_role = ALL
-- which is exactly the Supabase default. Rather than restate 84 identical
-- statements, grant broadly here and narrow in the sections that follow.
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 12b. Tables where anon and authenticated hold NOTHING (6)
-- ---------------------------------------------------------------------------
-- Live ACL: postgres=ALL, service_role=ALL. anon and authenticated absent.
REVOKE ALL ON TABLE
    public.personnel_engagements,
    public.whatsapp_link_tokens,
    public.whatsapp_optins,
    public.whatsapp_pending_contacts,
    public.whatsapp_processed_messages,
    public.whatsapp_sessions
  FROM anon, authenticated;

-- ---------------------------------------------------------------------------
-- 12c. Tables where anon holds nothing and authenticated holds SELECT only (5)
-- ---------------------------------------------------------------------------
-- Live ACL: postgres=ALL, service_role=ALL, authenticated=SELECT.
REVOKE ALL ON TABLE
    public.billing_profile_version_items,
    public.billing_profile_versions,
    public.invoice_generation_approvals,
    public.invoice_generation_candidates,
    public.invoice_generation_runs
  FROM anon, authenticated;
GRANT SELECT ON TABLE
    public.billing_profile_version_items,
    public.billing_profile_versions,
    public.invoice_generation_approvals,
    public.invoice_generation_candidates,
    public.invoice_generation_runs
  TO authenticated;

-- ---------------------------------------------------------------------------
-- 12d. whatsapp_disclosure_logs — service_role only, and without UPDATE
-- ---------------------------------------------------------------------------
-- Live ACL: postgres=arwdDxtm, service_role=arDxtm (note: no `w`/UPDATE).
-- The logs are append-and-read only, deliberately.
REVOKE ALL ON TABLE public.whatsapp_disclosure_logs FROM anon, authenticated;
REVOKE UPDATE ON TABLE public.whatsapp_disclosure_logs FROM service_role;

-- ---------------------------------------------------------------------------
-- 12e. resident_payment_cadence_summary — anon holds nothing
-- ---------------------------------------------------------------------------
REVOKE ALL ON TABLE public.resident_payment_cadence_summary FROM anon;

-- ---------------------------------------------------------------------------
-- 12f. Views — anon holds everything EXCEPT SELECT
-- ---------------------------------------------------------------------------
-- Live ACL on both views: anon=awdDxtm — every privilege except `r`/SELECT.
-- This is almost certainly not a deliberate design (writing to a view anon
-- cannot read is meaningless); it is reproduced faithfully and flagged for
-- owner review in the verification report.
REVOKE SELECT ON TABLE public.security_settings_view, public.visitor_analytics FROM anon;

-- ---------------------------------------------------------------------------
-- 12g. Function EXECUTE — the security-critical part
-- ---------------------------------------------------------------------------
-- Start from the broad default, then revoke. The four groups below are the
-- live database's actual four distinct function ACL shapes.

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated, service_role;

-- Group B (26 routines) — PUBLIC and anon REVOKED; authenticated + service_role
-- keep EXECUTE. These are the SECURITY DEFINER permission and identity helpers
-- and the invoice/settings machinery. Losing these revokes re-exposes them to
-- unauthenticated callers.
REVOKE EXECUTE ON FUNCTION
    public.create_generated_invoice(uuid, uuid),
    public.generate_access_code(),
    public.generate_resident_code(),
    public.get_effective_dashboard_theme(uuid),
    public.get_effective_portal_theme(uuid),
    public.get_effective_setting(text, uuid, uuid),
    public.get_frequent_visitors(integer, integer, integer),
    public.get_my_house_ids(),
    public.get_my_permissions(),
    public.get_my_resident_id(),
    public.get_my_role_name(),
    public.get_primary_occupier(uuid),
    public.get_setting_overrides(text),
    public.get_visitor_history_summary(uuid, integer),
    public.handle_new_user(),
    public.has_permission(text),
    public.import_legacy_financial_batch(jsonb),
    public.is_approved(),
    public.is_resident(),
    public.is_role_assignment_allowed(uuid, uuid),
    public.is_super_admin(),
    public.process_expired_approvals(),
    public.record_ownership_history(uuid, uuid, resident_role, text, resident_role, date, text, boolean, uuid),
    public.requires_approval_for_action(uuid, uuid, text),
    public.update_house_occupancy(),
    public.update_petty_cash_balance()
  FROM PUBLIC, anon;

-- Group C (7 routines) — PUBLIC REVOKED, anon retained.
REVOKE EXECUTE ON FUNCTION
    public.execute_property_transition(text, text, uuid, uuid, resident_role, jsonb, date, text, uuid),
    public.get_house_payment_status(uuid),
    public.get_resident_cross_property_payment_summary(uuid),
    public.get_resident_indebtedness(uuid),
    public.reverse_wallet_payment_batch(uuid, uuid),
    public.settle_wallet_invoices(uuid, uuid[], text, date, uuid, uuid, numeric, numeric, uuid),
    public.settle_wallet_invoices_idempotent(uuid, uuid, uuid[], text, date, uuid, uuid, numeric, numeric, uuid)
  FROM PUBLIC;

-- Group D (6 routines) — service_role ONLY. PUBLIC, anon and authenticated all
-- revoked. These are the privileged orchestration entry points.
REVOKE EXECUTE ON FUNCTION
    public.approve_invoice_generation_run(uuid, uuid, text),
    public.claim_invoice_generation_candidates(uuid, integer),
    public.create_personnel_resident_house_engagement(uuid, uuid, text, date, date),
    public.create_personnel_with_estate_engagement(jsonb, text, date, date),
    public.refresh_invoice_generation_run(uuid),
    public.replace_whatsapp_credentials(text, text, text, text, text, text, text, text, text, text, jsonb, uuid)
  FROM PUBLIC, anon, authenticated;

-- Group A (32 trigger/utility routines) keeps the default: PUBLIC, anon,
-- authenticated and service_role all hold EXECUTE. No statement needed.


